spec.expr:
(
  (node_filesystem_size_bytes{instance="$node", job="$job", mountpoint="/", fstype!="rootfs"}
   - node_filesystem_avail_bytes{instance="$node", job="$job", mountpoint="/", fstype!="rootfs"})
  / node_filesystem_size_bytes{instance="$node", job="$job", mountpoint="/", fstype!="rootfs"}
) * 100

topk(
  5,
  sum by (operation) (
    increase(
      mpi_duration_seconds_total{
        job=~"$job",
        instance=~"$node"
      }[$__range]
    )
  )
)

max(
  sum by (rank) (
    rate(mpi_calls_total{job=~"$job"}[1m])
  )
)
/
  avg(
    sum by (rank) (
      rate(mpi_calls_total{job=~"$job"}[1m])
    )
  )
